def main():
    target_path = os.path.join(os.path.dirname(__file__), "..", "lib", "data", "daily_reflections_data.dart")
    target_path = os.path.abspath(target_path)

    lines = []
    lines.append("// Generated comprehensive daily reflections library (120+ unique entries)")
    lines.append("// Each entry provides authentic Quranic Uthmani text, Surah reference,")
    lines.append("// deeply inspiring daily reflection, mood category, and EveryAyah recitation audio.")
    lines.append("")
    lines.append("import '../services/daily_reflection_service.dart';")
    lines.append("")
    lines.append("const List<DailyReflection> kDailyReflectionsLibrary = [")

    for item in RAW_REFLECTIONS:
        r_id, v_ar, surah, ayah, s_ref, refl, mood = item
        audio_url = f"https://everyayah.com/data/Alafasy_128kbps/{surah:03d}{ayah:03d}.mp3"
        # Escape quotes if any
        refl_esc = refl.replace("'", "\\'")
        lines.append("  DailyReflection(")
        lines.append(f"    id: {r_id},")
        lines.append(f"    verseArabic: '{v_ar}',")
        lines.append(f"    surahAndVerse: '{s_ref}',")
        lines.append(f"    reflection: '{refl_esc}',")
        lines.append(f"    moodCategory: '{mood}',")
        lines.append(f"    audioUrl: '{audio_url}',")
        lines.append("  ),")

    lines.append("];")
    lines.append("")

    with open(target_path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))

    print(f"Successfully generated {len(RAW_REFLECTIONS)} reflections into {target_path}")

if __name__ == "__main__":
    main()
